// Deterministic merge by taxpayerId + taxYear; flag duplicates and conflicts, never overwrite.
const items = $input.all().map(i => i.json);
const ret = { taxpayerId: items[0]?.taxpayerId, taxYear: items[0]?.taxYear, fields: {}, flags: [] };
for (const it of items) {
  let data = it;
  try { if (it.text) data = JSON.parse(it.text); } catch (e) { ret.flags.push('Unparseable output for ' + (it.recordId || 'unknown')); continue; }
  for (const f of (data.fields || [])) {
    const key = (data.form || '') + ':' + f.box;
    const entry = { value: f.value, status: f.status, recordId: data.recordId, box: f.box };
    if (ret.fields[key]) {
      if (ret.fields[key].value !== f.value) ret.flags.push('Conflict at ' + key);
      else ret.flags.push('Duplicate form at ' + key);
    } else ret.fields[key] = entry;
  }
}
return [{ json: { ...items[0], mergedReturn: ret, taxpayerId: ret.taxpayerId, taxYear: ret.taxYear } }];
